import numpy as np

from app.pipelines.rag.vector_store import LegalVectorStore


def main():
    document_id = "test-document"

    print("Creating FAISS vector store...")

    dimension = 1024
    store = LegalVectorStore(
        document_id=document_id,
        dimension=dimension,
    )

    print(f"Dimension: {dimension}")
    print("Vector store created successfully!")

    # Create test embeddings.
    # These simulate embeddings generated by BGE-M3.
    embeddings = np.array(
        [
            np.random.rand(dimension),
            np.random.rand(dimension),
            np.random.rand(dimension),
        ],
        dtype=np.float32,
    )

    # Normalize vectors because our FAISS index uses inner product.
    embeddings /= np.linalg.norm(
        embeddings,
        axis=1,
        keepdims=True,
    )

    metadata = [
        {
            "chunk_index": 0,
            "content": "The court dismissed the appeal.",
            "page_number": 1,
            "section_type": "decision",
        },
        {
            "chunk_index": 1,
            "content": "The appellant challenged the tribunal decision.",
            "page_number": 2,
            "section_type": "arguments",
        },
        {
            "chunk_index": 2,
            "content": "The court examined the evidence presented by both parties.",
            "page_number": 3,
            "section_type": "reasoning",
        },
    ]

    print()
    print("Adding vectors to FAISS...")
    store.add(embeddings, metadata)

    print(f"Vectors stored: {store.index.ntotal}")

    print()
    print("Saving FAISS index...")
    store.save()

    print("FAISS index saved successfully!")

    # Search using the second vector as the query.
    query_embedding = embeddings[1]

    print()
    print("Testing similarity search...")

    results = store.search(
        query_embedding,
        top_k=3,
    )

    for rank, result in enumerate(results, start=1):
      print(
        f"{rank}. "
        f"score={result['score']:.4f} | "
        f"{result['content']}"
    )

    print()
    print("VECTOR STORE TEST PASSED")


if __name__ == "__main__":
    main()